events = []
class Text(str):
    def __str__(self):
        raise AssertionError('str override')
    def __len__(self):
        raise AssertionError('len override')
    def __getitem__(self, key):
        raise AssertionError('getitem override')
    def __iter__(self):
        raise AssertionError('iter override')
class Result(float):
    def __new__(cls, value):
        events.append(('new', type(value).__name__, value.hex()))
        return float.__new__(cls, value)
    def __init__(self, value):
        events.append(('init', type(value).__name__, value.hex()))
try:
    value = float.fromhex(Text('0x1.8p+1'))
    actual = ('ok', type(value).__name__, value.hex(), events)
except BaseException as error:
    actual = ('error', type(error).__name__, str(error), events)

